import{_ as a,o as s,c as t,ag as r}from"./chunks/framework.DB9Ll7VW.js";const u=JSON.parse('{"title":"FAQs","description":"Frequently asked questions about Sikshya LMS — Free vs Pro, payments, themes, multisite, certificates, GDPR, multilingual, and the most-asked LMS questions.","frontmatter":{"title":"FAQs","description":"Frequently asked questions about Sikshya LMS — Free vs Pro, payments, themes, multisite, certificates, GDPR, multilingual, and the most-asked LMS questions."},"headers":[],"relativePath":"faqs.md","filePath":"faqs.md","lastUpdated":1778327862000}'),o={name:"faqs.md"};function i(n,e,l,d,h,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-an-lms-in-one-sentence" tabindex="-1">What is an LMS, in one sentence? <a class="header-anchor" href="#what-is-an-lms-in-one-sentence" aria-label="Permalink to &quot;What is an LMS, in one sentence?&quot;">​</a></h3><p>A <strong>learning management system</strong> is software that hosts your lessons, tracks who finished what, and often handles enrollment or payment — so you&#39;re not emailing PDFs and spreadsheets by hand.</p><h3 id="is-sikshya-lms-free" tabindex="-1">Is Sikshya LMS free? <a class="header-anchor" href="#is-sikshya-lms-free" aria-label="Permalink to &quot;Is Sikshya LMS free?&quot;">​</a></h3><p>Yes. The free plugin ships a complete LMS — courses, lessons, quizzes, assignments, certificates, native checkout with PayPal, coupons, orders, learner dashboards, and email notifications.</p><p><strong>Sikshya Pro</strong> is a separate plugin that unlocks licensed add-ons (drip, gradebook, subscriptions, premium gateways, marketplace, white label, etc.). See <a href="/docs/third-party-integrations">Pro add-ons</a>.</p><h3 id="do-i-need-coding-skills" tabindex="-1">Do I need coding skills? <a class="header-anchor" href="#do-i-need-coding-skills" aria-label="Permalink to &quot;Do I need coding skills?&quot;">​</a></h3><p>No for day-to-day course building. Developers can extend Sikshya with <a href="/docs/hooks-filters">hooks and filters</a> and the <a href="/docs/api-reference">REST API</a>.</p><h3 id="what-s-the-difference-between-sikshya-and-sikshya-pro" tabindex="-1">What&#39;s the difference between Sikshya and Sikshya Pro? <a class="header-anchor" href="#what-s-the-difference-between-sikshya-and-sikshya-pro" aria-label="Permalink to &quot;What&#39;s the difference between Sikshya and Sikshya Pro?&quot;">​</a></h3><p>Sikshya is the free plugin. Sikshya Pro is a separate plugin that requires Sikshya to be installed first. Pro unlocks licensed add-ons and premium gateways.</p><h3 id="what-urls-does-sikshya-create" tabindex="-1">What URLs does Sikshya create? <a class="header-anchor" href="#what-urls-does-sikshya-create" aria-label="Permalink to &quot;What URLs does Sikshya create?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>What it shows</th></tr></thead><tbody><tr><td><code>/courses/</code></td><td>Public course catalog</td></tr><tr><td><code>/{course-slug}/</code></td><td>Single course page</td></tr><tr><td><code>/cart/</code></td><td>Cart</td></tr><tr><td><code>/checkout/</code></td><td>Checkout</td></tr><tr><td><code>/my-learning/</code></td><td>Learner account</td></tr><tr><td><code>/learn/</code></td><td>Learn hub (after enrolling)</td></tr><tr><td><code>/login/</code></td><td>Login form</td></tr><tr><td><code>/order/</code></td><td>Order receipt</td></tr></tbody></table><p>You can rename any slug under <span class="screen-path">Sikshya → Settings → Permalinks</span>.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><h3 id="does-sikshya-work-with-any-wordpress-theme" tabindex="-1">Does Sikshya work with any WordPress theme? <a class="header-anchor" href="#does-sikshya-work-with-any-wordpress-theme" aria-label="Permalink to &quot;Does Sikshya work with any WordPress theme?&quot;">​</a></h3><p>Yes — designed for broad theme compatibility. If layouts clash, briefly switch to a default theme (Twenty Twenty-Five) to isolate theme CSS. You can override any Sikshya template by copying it from <code>wp-content/plugins/sikshya/templates/</code> to <code>wp-content/themes/{theme}/sikshya/</code>.</p><h3 id="does-sikshya-work-with-the-block-editor" tabindex="-1">Does Sikshya work with the block editor? <a class="header-anchor" href="#does-sikshya-work-with-the-block-editor" aria-label="Permalink to &quot;Does Sikshya work with the block editor?&quot;">​</a></h3><p>Yes. Use Shortcode blocks for <code>[sikshya_courses]</code>, <code>[sikshya_login]</code>, and <code>[sikshya_registration]</code>. Course pages and learner templates work alongside block-based pages and FSE themes.</p><h3 id="does-sikshya-work-with-elementor-divi-bricks-oxygen" tabindex="-1">Does Sikshya work with Elementor / Divi / Bricks / Oxygen? <a class="header-anchor" href="#does-sikshya-work-with-elementor-divi-bricks-oxygen" aria-label="Permalink to &quot;Does Sikshya work with Elementor / Divi / Bricks / Oxygen?&quot;">​</a></h3><p>Yes — all of them. Use a Posts widget targeting the <code>sik_course</code> post type, plus a Shortcode widget for catalog or auth forms. See <a href="/docs/elementor-integration">Blocks &amp; page builders</a>.</p><h3 id="can-i-use-woocommerce-instead" tabindex="-1">Can I use WooCommerce instead? <a class="header-anchor" href="#can-i-use-woocommerce-instead" aria-label="Permalink to &quot;Can I use WooCommerce instead?&quot;">​</a></h3><p>The free core emphasizes native course checkout for speed and clarity. WooCommerce can run <strong>alongside</strong> Sikshya — see <a href="/docs/woocommerce-integration">WooCommerce co-existence</a>.</p><h3 id="is-sikshya-multisite-compatible" tabindex="-1">Is Sikshya multisite compatible? <a class="header-anchor" href="#is-sikshya-multisite-compatible" aria-label="Permalink to &quot;Is Sikshya multisite compatible?&quot;">​</a></h3><p>Yes — <code>Network: true</code>. Each subsite has its own data. The Pro <strong>Multisite &amp; network license tools</strong> add-on helps you manage licenses across subsites.</p><h2 id="selling-courses" tabindex="-1">Selling courses <a class="header-anchor" href="#selling-courses" aria-label="Permalink to &quot;Selling courses&quot;">​</a></h2><h3 id="how-do-i-sell-courses" tabindex="-1">How do I sell courses? <a class="header-anchor" href="#how-do-i-sell-courses" aria-label="Permalink to &quot;How do I sell courses?&quot;">​</a></h3><ol class="step-list"><li>Create a paid course, set a price.</li><li>Connect <strong>PayPal</strong> (free) or <strong>Stripe / Razorpay / Mollie / Paystack / Square / Authorize.Net</strong> <span class="pro-pill">PRO</span> under <span class="screen-path">Sikshya → Settings → Payment</span>.</li><li>Run a test transaction with sandbox keys.</li><li>Switch to live keys.</li></ol><p>See <a href="/docs/payment-settings">Payments</a> for the full guide.</p><h3 id="what-payment-gateways-does-the-free-plugin-support" tabindex="-1">What payment gateways does the free plugin support? <a class="header-anchor" href="#what-payment-gateways-does-the-free-plugin-support" aria-label="Permalink to &quot;What payment gateways does the free plugin support?&quot;">​</a></h3><p>The free plugin ships <strong>PayPal</strong> (fully working) and <strong>Offline / manual</strong> (admin marks orders paid). <strong>Stripe is not in the free plugin</strong> — Stripe is a Pro-only add-on, along with <strong>Razorpay</strong>, <strong>Mollie</strong>, <strong>Paystack</strong>, <strong>Square</strong>, <strong>Authorize.Net</strong>, and <strong>Bank Transfer</strong>. Activate Sikshya Pro and toggle the gateway on under <span class="screen-path">Sikshya → Add-ons</span>.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Six premium gateways + bank transfer</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Compare Sikshya Pro plans →</a></div><h3 id="does-sikshya-support-subscriptions" tabindex="-1">Does Sikshya support subscriptions? <a class="header-anchor" href="#does-sikshya-support-subscriptions" aria-label="Permalink to &quot;Does Sikshya support subscriptions?&quot;">​</a></h3><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Recurring memberships</span></div><p class="pro-callout__desc">Recurring billing is part of the <strong>Subscriptions</strong> add-on (Pro / Growth tier). The free tier focuses on one-time and free-course selling.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock subscriptions →</a></div><h3 id="can-i-issue-refunds" tabindex="-1">Can I issue refunds? <a class="header-anchor" href="#can-i-issue-refunds" aria-label="Permalink to &quot;Can I issue refunds?&quot;">​</a></h3><p>You can mark an order as <strong>Refunded</strong> in Sikshya, which revokes enrollment and writes the refund metadata. The actual money movement happens in the gateway dashboard. Refund first in the gateway dashboard, then mark refunded in Sikshya — that&#39;s the most reliable workflow.</p><h3 id="how-do-coupons-work" tabindex="-1">How do coupons work? <a class="header-anchor" href="#how-do-coupons-work" aria-label="Permalink to &quot;How do coupons work?&quot;">​</a></h3><p>The free plugin supports percentage or fixed discounts, redemption limits, and optional date windows. The Pro <strong>Advanced coupons</strong> add-on adds minimum cart total, exclusions, first-time-buyer rules, and stacking guards. See <a href="/docs/enrollment-settings#coupons-free">Enrollment &amp; access</a>.</p><h2 id="learners" tabindex="-1">Learners <a class="header-anchor" href="#learners" aria-label="Permalink to &quot;Learners&quot;">​</a></h2><h3 id="how-do-learners-enroll" tabindex="-1">How do learners enroll? <a class="header-anchor" href="#how-do-learners-enroll" aria-label="Permalink to &quot;How do learners enroll?&quot;">​</a></h3><ul><li><strong>Free courses:</strong> sign in, click <strong>Enroll</strong>.</li><li><strong>Paid courses:</strong> sign in, add to cart, pay at checkout.</li><li><strong>Manual:</strong> an admin enrolls them from <span class="screen-path">People → Enrollments</span>.</li></ul><h3 id="what-happens-after-a-learner-completes-a-course" tabindex="-1">What happens after a learner completes a course? <a class="header-anchor" href="#what-happens-after-a-learner-completes-a-course" aria-label="Permalink to &quot;What happens after a learner completes a course?&quot;">​</a></h3><p>Sikshya marks the course complete, fires <code>sikshya_course_completed</code>, issues a <strong>certificate</strong> (basic in free; advanced builder + QR in Pro), sends the <strong>Course completed</strong> + <strong>Certificate issued</strong> emails, and updates progress.</p><h3 id="can-learners-see-only-their-own-data" tabindex="-1">Can learners see only their own data? <a class="header-anchor" href="#can-learners-see-only-their-own-data" aria-label="Permalink to &quot;Can learners see only their own data?&quot;">​</a></h3><p>Yes. Capability checks are enforced everywhere. Learners get the <code>sikshya_student</code> role, scoped to their own enrollments, attempts, certificates, and account.</p><h3 id="do-you-support-drip-cohort-programs" tabindex="-1">Do you support drip / cohort programs? <a class="header-anchor" href="#do-you-support-drip-cohort-programs" aria-label="Permalink to &quot;Do you support drip / cohort programs?&quot;">​</a></h3><p>The free plugin supports <strong>sequential progression</strong> (each lesson unlocks after the previous).</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Drip + drip notifications + prerequisites</span></div><p class="pro-callout__desc">Date-based, X-days, and cohort drip — plus &quot;lesson unlocked&quot; emails — live in the <strong>Content drip</strong>, <strong>Drip notifications</strong>, and <strong>Prerequisites</strong> add-ons.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock drip &amp; cohorts →</a></div><h2 id="quizzes-assessment" tabindex="-1">Quizzes &amp; assessment <a class="header-anchor" href="#quizzes-assessment" aria-label="Permalink to &quot;Quizzes &amp; assessment&quot;">​</a></h2><h3 id="what-quiz-types-are-supported" tabindex="-1">What quiz types are supported? <a class="header-anchor" href="#what-quiz-types-are-supported" aria-label="Permalink to &quot;What quiz types are supported?&quot;">​</a></h3><p>Free: <strong>multiple choice</strong>, <strong>true / false</strong>, <strong>short answer</strong>, <strong>fill in the blank</strong>.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Question banks &amp; advanced quizzes</span></div><p class="pro-callout__desc">Question banks, randomization, random pools per learner, and advanced types are part of the <strong>Advanced quiz types</strong> add-on.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced quizzes →</a></div><h3 id="do-you-support-assignments" tabindex="-1">Do you support assignments? <a class="header-anchor" href="#do-you-support-assignments" aria-label="Permalink to &quot;Do you support assignments?&quot;">​</a></h3><p>Yes — basic in free (file upload + pass / fail). Advanced (rubrics, restricted file types, resubmissions, grading queue) is the <strong>Advanced assignments</strong> + <strong>Gradebook</strong> Pro add-ons.</p><h3 id="do-you-support-a-gradebook" tabindex="-1">Do you support a gradebook? <a class="header-anchor" href="#do-you-support-a-gradebook" aria-label="Permalink to &quot;Do you support a gradebook?&quot;">​</a></h3><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Gradebook</span></div><p class="pro-callout__desc">The <strong>Gradebook</strong> add-on consolidates quiz scores and graded assignments into a per-learner / per-course view, with export and drilldown.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock the gradebook →</a></div><h2 id="certificates" tabindex="-1">Certificates <a class="header-anchor" href="#certificates" aria-label="Permalink to &quot;Certificates&quot;">​</a></h2><h3 id="are-certificates-included" tabindex="-1">Are certificates included? <a class="header-anchor" href="#are-certificates-included" aria-label="Permalink to &quot;Are certificates included?&quot;">​</a></h3><p>Yes — the free plugin issues certificates on course completion using two presets (Regalia and Vertex).</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced certificates with QR verification</span></div><p class="pro-callout__desc">The <strong>Advanced certificates</strong> add-on adds a drag-and-drop builder, more merge fields, and QR codes that link to a public verify page.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced certificates →</a></div><h3 id="can-certificates-be-verified-externally" tabindex="-1">Can certificates be verified externally? <a class="header-anchor" href="#can-certificates-be-verified-externally" aria-label="Permalink to &quot;Can certificates be verified externally?&quot;">​</a></h3><p>Yes (Pro). The QR code on the certificate links to a public verify URL (<code>/wp-json/sikshya/v1/public/certificates/verify?serial=...</code>). Anyone can verify a certificate without authentication.</p><h2 id="privacy-gdpr-data-ownership" tabindex="-1">Privacy, GDPR, data ownership <a class="header-anchor" href="#privacy-gdpr-data-ownership" aria-label="Permalink to &quot;Privacy, GDPR, data ownership&quot;">​</a></h2><h3 id="is-my-data-shared-with-mantrabrain" tabindex="-1">Is my data shared with Mantrabrain? <a class="header-anchor" href="#is-my-data-shared-with-mantrabrain" aria-label="Permalink to &quot;Is my data shared with Mantrabrain?&quot;">​</a></h3><p>No. Sikshya is self-hosted — every learner record, order, certificate, and quiz attempt lives in your WordPress database. Optional, opt-in <strong>usage insights</strong> can be enabled / disabled (off by default).</p><h3 id="is-sikshya-gdpr-compliant" tabindex="-1">Is Sikshya GDPR-compliant? <a class="header-anchor" href="#is-sikshya-gdpr-compliant" aria-label="Permalink to &quot;Is Sikshya GDPR-compliant?&quot;">​</a></h3><p>Sikshya is built on WordPress and stores user data in your own site. WordPress&#39;s standard <strong>Tools → Export Personal Data</strong> and <strong>Erase Personal Data</strong> flows work for Sikshya data.</p><h3 id="how-do-i-report-a-security-vulnerability" tabindex="-1">How do I report a security vulnerability? <a class="header-anchor" href="#how-do-i-report-a-security-vulnerability" aria-label="Permalink to &quot;How do I report a security vulnerability?&quot;">​</a></h3><p>Email <code>mantrabrain@gmail.com</code> privately with details. Don&#39;t post exploit steps in public reviews.</p><h2 id="translation" tabindex="-1">Translation <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Translation&quot;">​</a></h2><h3 id="can-i-translate-sikshya" tabindex="-1">Can I translate Sikshya? <a class="header-anchor" href="#can-i-translate-sikshya" aria-label="Permalink to &quot;Can I translate Sikshya?&quot;">​</a></h3><p>Yes — text domain is <code>sikshya</code> (free) and <code>sikshya-pro</code> (Pro). Loco Translate, WPML, TranslatePress, Polylang, and Weglot all work.</p><h3 id="multilingual-catalog" tabindex="-1">Multilingual catalog? <a class="header-anchor" href="#multilingual-catalog" aria-label="Permalink to &quot;Multilingual catalog?&quot;">​</a></h3><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multilingual (WPML / Weglot)</span></div><p class="pro-callout__desc">The <strong>Multilingual</strong> add-on registers Sikshya strings for translation in WPML / Weglot.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock multilingual →</a></div><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="how-many-courses-students-can-sikshya-handle" tabindex="-1">How many courses / students can Sikshya handle? <a class="header-anchor" href="#how-many-courses-students-can-sikshya-handle" aria-label="Permalink to &quot;How many courses / students can Sikshya handle?&quot;">​</a></h3><p>There are no hardcoded limits. Performance is driven by your hosting (PHP-FPM workers, MySQL configuration, page cache). For 10k+ learners and heavy reporting, the Pro <strong>Advanced analytics &amp; exports</strong> + <strong>Enterprise reporting</strong> add-ons + a managed-WordPress host or VPS is the right combination.</p><h3 id="will-sikshya-hurt-my-seo" tabindex="-1">Will Sikshya hurt my SEO? <a class="header-anchor" href="#will-sikshya-hurt-my-seo" aria-label="Permalink to &quot;Will Sikshya hurt my SEO?&quot;">​</a></h3><p>No. Sikshya outputs normal WordPress pages and URLs. Yoast / Rank Math / SEOPress all index Sikshya correctly.</p><h2 id="developer" tabindex="-1">Developer <a class="header-anchor" href="#developer" aria-label="Permalink to &quot;Developer&quot;">​</a></h2><h3 id="where-s-the-rest-api-documentation" tabindex="-1">Where&#39;s the REST API documentation? <a class="header-anchor" href="#where-s-the-rest-api-documentation" aria-label="Permalink to &quot;Where&#39;s the REST API documentation?&quot;">​</a></h3><p><a href="/docs/api-reference">REST API</a>. Routes live under <code>/wp-json/sikshya/v1/</code>.</p><h3 id="where-are-the-hooks-and-filters" tabindex="-1">Where are the hooks and filters? <a class="header-anchor" href="#where-are-the-hooks-and-filters" aria-label="Permalink to &quot;Where are the hooks and filters?&quot;">​</a></h3><p><a href="/docs/hooks-filters">Hooks &amp; filters</a>. Free + Pro share the same <code>sikshya_*</code> action / filter naming.</p><h2 id="pricing-support" tabindex="-1">Pricing &amp; support <a class="header-anchor" href="#pricing-support" aria-label="Permalink to &quot;Pricing &amp; support&quot;">​</a></h2><h3 id="where-can-i-get-help" tabindex="-1">Where can I get help? <a class="header-anchor" href="#where-can-i-get-help" aria-label="Permalink to &quot;Where can I get help?&quot;">​</a></h3><ul><li><a href="https://www.facebook.com/groups/sikshyalms/" target="_blank" rel="noreferrer">Sikshya LMS Facebook Community</a> — peer discussion.</li><li><a href="https://wordpress.org/support/plugin/sikshya/" target="_blank" rel="noreferrer">WordPress.org support forum</a> — public threads.</li><li><a href="https://github.com/MantraBrain" target="_blank" rel="noreferrer">GitHub</a> — bug reports.</li><li><a href="https://mantrabrain.com/contact/" target="_blank" rel="noreferrer">Mantrabrain priority support</a> — Pro license holders.</li></ul><p>See <a href="/docs/support">Support</a> for routing details.</p>',88)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
